from collections import Counter


class EventProcessor:
    def __init__(self):
        self._events: list[dict] = []
        self._types: Counter[str] = Counter()

    def ingest(self, event: dict) -> None:
        self._events.append(event)
        self._types[event["type"]] += 1

    def count(self, event_type: str | None = None) -> int:
        return len(self._events) if event_type is None else self._types[event_type]

    def active_users(self, start: int, end: int) -> list[str]:
        return sorted({e["user"] for e in self._events if start <= e["ts"] < end})

