from collections import Counter, defaultdict


class EventProcessor:
    def __init__(self, session_gap: int = 1800):
        self.session_gap = session_gap
        self._events: list[dict] = []
        self._types: Counter[str] = Counter()
        # user -> list of [start, end, count], built incrementally (events arrive in order)
        self._sessions: dict[str, list[list[int]]] = defaultdict(list)

    def ingest(self, event: dict) -> None:
        self._events.append(event)
        self._types[event["type"]] += 1
        sessions = self._sessions[event["user"]]
        ts = event["ts"]
        if sessions and ts - sessions[-1][1] <= self.session_gap:
            sessions[-1][1] = ts
            sessions[-1][2] += 1
        else:
            sessions.append([ts, ts, 1])

    def count(self, event_type: str | None = None) -> int:
        return len(self._events) if event_type is None else self._types[event_type]

    def active_users(self, start: int, end: int) -> list[str]:
        return sorted({e["user"] for e in self._events if start <= e["ts"] < end})

    def sessions(self, user: str) -> list[tuple[int, int, int]]:
        return [tuple(s) for s in self._sessions.get(user, [])]

