import bisect
from collections import Counter, defaultdict


class EventProcessor:
    def __init__(self, session_gap: int = 1800, allowed_lateness: int | None = None):
        self.session_gap = session_gap
        self.allowed_lateness = allowed_lateness
        self._types: Counter[str] = Counter()
        self._times: dict[str, list[int]] = defaultdict(list)  # user -> sorted timestamps
        self._total = 0
        self._watermark: int | None = None
        self._dropped = 0

    def _is_late(self, ts: int) -> bool:
        return (
            self.allowed_lateness is not None
            and self._watermark is not None
            and ts < self._watermark - self.allowed_lateness
        )

    def ingest(self, event: dict) -> None:
        ts = event["ts"]
        if self._is_late(ts):
            self._dropped += 1
            return
        self._watermark = ts if self._watermark is None else max(self._watermark, ts)
        self._total += 1
        self._types[event["type"]] += 1
        bisect.insort(self._times[event["user"]], ts)

    def count(self, event_type: str | None = None) -> int:
        return self._total if event_type is None else self._types[event_type]

    def active_users(self, start: int, end: int) -> list[str]:
        active = []
        for user, times in self._times.items():
            i = bisect.bisect_left(times, start)
            if i < len(times) and times[i] < end:
                active.append(user)
        return sorted(active)

    def sessions(self, user: str) -> list[tuple[int, int, int]]:
        result: list[tuple[int, int, int]] = []
        start = prev = None
        count = 0
        for ts in self._times.get(user, []):
            if prev is not None and ts - prev > self.session_gap:
                result.append((start, prev, count))
                start, count = ts, 0
            if start is None:
                start = ts
            prev = ts
            count += 1
        if start is not None:
            result.append((start, prev, count))
        return result

    def dropped(self) -> int:
        return self._dropped

